/* Browser-local agency team profiles. Real authentication remains unconnected. */
let activeMember='admin';
function memberNow(){return state.members?.find(m=>m.id===activeMember&&m.agency===agency)}
function isAgencyAdmin(){return role==='manager'&&activeMember==='admin'}
function canSeeProperty(p){if(!p)return false;if(role==='sevlink')return true;if(p.agency!==agency)return false;if(role==='tenant')return p.id===state.tenants.find(t=>t.id===tenant)?.property;return isAgencyAdmin()||p.manager===memberNow()?.id}
const normaliseBeforeTeam=normalise;normalise=function(){normaliseBeforeTeam();state.members??=[];for(const a of state.agencies.filter(a=>!a.archivedForAgencyOnly)){if(!state.cleanStart&&!state.members.some(m=>m.agency===a.id))state.members.push({id:'pm-'+a.id,agency:a.id,name:a.contact||'Property manager',email:a.email||'',phone:a.phone||''});for(const p of state.properties.filter(p=>p.agency===a.id))if(!p.manager)p.manager=role==='manager'&&a.id===agency&&memberNow()?activeMember:state.members.find(m=>m.agency===a.id)?.id||'unassigned'}if(activeMember!=='admin'&&!memberNow())activeMember='admin'};
const jobsBeforeTeam=visibleJobs;visibleJobs=function(){return jobsBeforeTeam().filter(j=>canSeeProperty(property(j.property)))};
const personBeforeTeam=person;person=function(){return role==='manager'?(isAgencyAdmin()?agencyNow().contact+' · Agency admin':memberNow()?.name):personBeforeTeam()};
function switchMember(value){if(value!=='admin'&&!state.members.some(m=>m.id===value&&m.agency===agency))return;activeMember=value;filter='All statuses';query='';navigate('overview')}
const agencyFormBeforeTeam=agencyForm;agencyForm=function(fresh){if(role==='manager'&&(fresh||!isAgencyAdmin())){toast('Agency profiles are managed by the agency admin.');return}if(role==='tenant')return;agencyFormBeforeTeam(fresh)};
const propertyFormBeforeTeam=propertyForm;propertyForm=function(pid){if(role!=='manager'||pid&&!canSeeProperty(property(pid)))return;propertyFormBeforeTeam(pid)};
const tenantFormBeforeTeam=tenantForm;tenantForm=function(pid='',tid=''){if(role!=='manager'||pid&&!canSeeProperty(property(pid))||tid&&!state.tenants.some(t=>t.id===tid&&canSeeProperty(property(t.property))))return;tenantFormBeforeTeam(pid,tid)};
function renderTeam(){if(!isAgencyAdmin()){app.innerHTML=heading('Agency admin access required.','Team management is available to your agency admin.');return}const members=state.members.filter(m=>m.agency===agency);app.innerHTML=heading('Your property management team.','Each PM manages their own portfolio. The agency admin sees the whole agency.','<button class="primary" onclick="memberForm()">＋ Add property manager</button>')+`<div class="notice">Demo profiles: click a name to preview their workspace. Individual sign-ins and emailed invitations are not connected.</div><div class="cards">${members.map(m=>`<div class="card"><h2><button class="secondary" onclick="switchMember('${m.id}')">${esc(m.name)} →</button></h2><p>${esc(m.email)}<br>${esc(m.phone)}</p><p>${state.properties.filter(p=>p.manager===m.id&&p.agency===agency).length} assigned properties</p><button class="secondary" onclick="memberForm('${m.id}')">Edit profile / assign properties</button></div>`).join('')}</div>`}
function memberForm(mid){if(!isAgencyAdmin())return;const m=state.members.find(m=>m.id===mid&&m.agency===agency)||{},props=state.properties.filter(p=>p.agency===agency);openForm(mid?'Edit property manager.':'Add property manager.',field('Full name','name',m.name)+field('Email','email',m.email,'email')+field('Phone (optional)','phone',m.phone,'tel',false)+`<label>Assigned properties</label><p>Select this PM’s portfolio. Reassigning a property also updates its tenants’ PM contact.</p>${props.map(p=>`<label style="display:flex;gap:10px"><input style="width:auto" type="checkbox" name="property-${p.id}" ${p.manager===mid?'checked':''}>${esc(p.address)} · ${esc(p.name)}</label>`).join('')}<div class="notice">Profile saved in this demo only. No invitation email is sent.</div>`,'Save PM profile',async d=>{if(!isAgencyAdmin())return;const email=String(d.get('email')||'').trim();if(state.members.some(x=>x.agency===agency&&x.id!==mid&&x.email.toLowerCase()===email.toLowerCase())){toast('This email already has a PM profile in your agency.');return}if(await commit(()=>{const member=m.id?m:{id:id('pm'),agency};Object.assign(member,{name:String(d.get('name')).trim(),email,phone:d.get('phone')||''});if(!m.id)state.members.push(member);for(const p of props){if(d.get('property-'+p.id))p.manager=member.id;else if(p.manager===member.id)p.manager='unassigned'}})){modal.close();navigate('team');toast('PM profile saved. No email sent.')}})}
function assignPropertyForm(pid){if(!isAgencyAdmin())return;const p=property(pid);if(p?.agency!==agency)return;openForm('Assign property manager.',`<p><b>${esc(p.address)}</b><br>${esc(p.name)}</p><label>Property manager</label><select name="manager"><option value="unassigned">Unassigned · agency admin manages</option>${state.members.filter(m=>m.agency===agency).map(m=>`<option value="${m.id}" ${m.id===p.manager?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`,'Save assignment',async d=>{if(!isAgencyAdmin())return;const value=d.get('manager');if(value!=='unassigned'&&!state.members.some(m=>m.id===value&&m.agency===agency))return;if(await commit(()=>p.manager=value)){modal.close();render()}})}
const propertiesBeforeTeam=renderProperties;renderProperties=function(){propertiesBeforeTeam();const props=state.properties.filter(p=>canSeeProperty(p));app.insertAdjacentHTML('beforeend',`<div class="panel" style="margin-top:20px"><h2>Property managers</h2>${props.map(p=>`<div class="listline"><b>${esc(p.address)} · ${esc(p.name)}</b><p>PM: ${esc(state.members.find(m=>m.id===p.manager)?.name||'Unassigned · agency admin')}</p>${isAgencyAdmin()?`<button class="secondary" onclick="assignPropertyForm('${p.id}')">Assign / change PM</button>`:''}</div>`).join('')}</div>`)};
const profileBeforeTeam=renderProfile;renderProfile=function(){if(isAgencyAdmin())return profileBeforeTeam();if(role!=='manager')return;const m=memberNow();app.innerHTML=heading('Your property manager profile.',agencyNow().name)+`<div class="card"><h2>${esc(m?.name)}</h2><p>${esc(m?.email)}<br>${esc(m?.phone)}</p><p>${state.properties.filter(p=>canSeeProperty(p)).length} properties in your portfolio.</p></div>`};
function tenantHomeSummary(){const t=state.tenants.find(t=>t.id===tenant&&t.agency===agency),p=property(t?.property),m=state.members.find(m=>m.id===p?.manager);return `<div class="panel" style="margin-bottom:20px"><span class="eyebrow">YOUR PROPERTY</span><h2>${esc(p?.address||'No property linked')}</h2><p>${esc(p?.name||'')}</p><b>Your property manager: ${esc(m?.name||agencyNow().contact)}</b><p>${esc(m?.email||agencyNow().email)}<br>${esc(m?.phone||agencyNow().phone)}</p></div>`}
const renderBeforeTeam=render;render=function(){renderBeforeTeam();if(!state)return;if(role!=='sevlink'){$('#newAgency')?.remove();$('#agencySwitch')?.remove()}if(role==='manager'){$('#nav').insertAdjacentHTML('afterbegin',`<label>DEMO PROFILE PREVIEW</label><select id="memberSwitch" aria-label="Preview agency team profile"><option value="admin">Agency admin · whole portfolio</option>${state.members.filter(m=>m.agency===agency).map(m=>`<option value="${m.id}" ${m.id===activeMember?'selected':''}>${esc(m.name)} · Property manager</option>`).join('')}</select>`);$('#memberSwitch').value=activeMember;$('#memberSwitch').onchange=e=>switchMember(e.target.value);if(isAgencyAdmin())$('#nav').insertAdjacentHTML('beforeend',`<button data-view="team" class="${view==='team'?'active':''}">♙ &nbsp; Manage team</button>`);if(view==='team')renderTeam();if(!isAgencyAdmin()&&['overview','requests'].includes(view))app.insertAdjacentHTML('afterbegin',`<div class="banner"><b>${esc(memberNow()?.name)} · My portfolio</b><br>Properties, repairs, tenants and invoices assigned to you.</div>`)}if(role==='tenant'){if(['overview','requests','report'].includes(view))app.insertAdjacentHTML('afterbegin',tenantHomeSummary());if(['properties','tenants','profile','team','recurring'].includes(view))app.innerHTML=tenantHomeSummary()}};


const brandingBeforeTeam=brandingForm;brandingForm=function(){if(isAgencyAdmin())brandingBeforeTeam()};
const historyBeforeTeam=propertyHistory;propertyHistory=function(pid){if(canSeeProperty(property(pid)))historyBeforeTeam(pid)};
function attentionItems(){if(role!=='manager')return [];return visibleJobs().flatMap(j=>{const items=[];if(j.sentToSevlink===false)items.push({j,section:'comments',label:'Tenant report awaiting review'});if(j.sentToSevlink!==false&&j.quotes.some(q=>q.status==='Pending'))items.push({j,section:'quotes',label:'Quote awaiting approval'});for(const i of j.invoices.filter(i=>invoiceBalance(i)>0))items.push({j,section:'invoices',label:(isOverdue(i)?'Overdue invoice: ':'Unpaid invoice: ')+i.number+' · '+money(invoiceBalance(i))});return items})}
function attentionMarkup(){const items=attentionItems();return `<div class="panel" style="margin-bottom:22px"><div class="panelhead"><h2>Needs your attention <span class="badge">${items.length}</span></h2><small>${isAgencyAdmin()?'Whole agency':'Your portfolio'}</small></div>${items.map(({j,section,label})=>`<div class="listline toolbar"><div style="flex:1"><strong class="agent-address">${esc(property(j.property)?.address)}</strong><b>${esc(label)}</b><p>${esc(j.title)} · ${j.ref}</p></div><button class="primary" onclick="${j.sentToSevlink===false?`reviewTenantReportForm('${j.id}')`:`jobDetail('${j.id}','${section}')`}">Review →</button></div>`).join('')||'<p>You’re up to date. No tenant reports, quote approvals or unpaid invoices need attention.</p>'}</div>`}
const renderBeforeAttention=render;render=function(){renderBeforeAttention();if(role==='manager'&&view==='overview')app.insertAdjacentHTML('afterbegin',attentionMarkup())};


const tenantSelectorBeforeTeam=tenantSelector;tenantSelector=function(){if(role==='tenant')return `<p class="muted">Tenant profile: ${esc(state.tenants.find(t=>t.id===tenant)?.name||'No tenant linked')}</p>`;return tenantSelectorBeforeTeam()};

